"""
Wasm struct field indices for fields that are accessed explicitly from Wasm code, e.g. in
intrinsics: each dart `static const` a function of no arguments, `FieldIndex_<name>()`, Julia having
no static members. dart never makes a FieldIndex; its implicit constructor is the struct's one.
"""
@parity "dart2wasm/lib/class_info.dart:18 FieldIndex" struct FieldIndex
    FieldIndex() = new()
end

"""
Information about the Wasm representation for a class: its Julia class (`nothing` for the top
type, which has none), class id, depth in the Wasm type hierarchy, struct, the class info it sits
below, and the reference types to its struct; its representation type and cyclicness are filled
by ClassInfoCollector.collect.

`typeParameterMatch` maps a class's type parameters to the superclass's ones it reuses. Julia's
classes are instances (`Vector{Int64}`, its parameters bound), so no class has a type parameter left
to store and the map is empty.
"""
@parity "dart2wasm/lib/class_info.dart:199 ClassInfo" mutable struct ClassInfo
    const cls::Union{DataType,Nothing}
    const _class_id::Int
    const depth::Int
    const struct_::WasmBuilder.IR.StructType
    const super_info::Union{ClassInfo,Nothing}
    const type_parameter_match::IdDict{TypeVar,TypeVar}
    _repr::Union{WasmBuilder.IR.RefType,Nothing}
    _cyclic::Union{Bool,Nothing}
    const nullable_type::WasmBuilder.IR.RefType
    const non_nullable_type::WasmBuilder.IR.RefType
    # the struct's one constructor, tagged, every final field given; dart's constructor at :268 is its
    # outer function, which makes the two reference types
    ClassInfo(::Val{:_}, cls::Union{DataType,Nothing}, _class_id::Int, depth::Int, struct_::WasmBuilder.IR.StructType,
              super_info::Union{ClassInfo,Nothing}, type_parameter_match::IdDict{TypeVar,TypeVar},
              nullable_type::WasmBuilder.IR.RefType, non_nullable_type::WasmBuilder.IR.RefType) =
        new(cls, _class_id, depth, struct_, super_info, type_parameter_match, nothing, nothing, nullable_type, non_nullable_type)
end

"""
Constructs the Wasm type hierarchy: a struct for each class of the closed world, below the
artificial top struct, with its fields, its representation type and its cyclicness.

`typeType`, the field type of a class's type parameter, is read only for type parameters, which
Julia's classes, instances with their parameters bound, do not have. The translator is held as
`KernelNodes` (src/translator.jl).
"""
@parity "dart2wasm/lib/class_info.dart:346 ClassInfoCollector" struct ClassInfoCollector
    translator::KernelNodes
    top_info::Late{ClassInfo}
    _record_structs::Dict{Int,WasmBuilder.IR.StructType}
    masqueraded::Late{Base.IdSet{DataType}}
    type_type::Late{WasmBuilder.IR.FieldType}
    # the struct's one constructor, tagged, with dart's field initializers; dart's constructor at
    # :406 is its outer function; the late masqueraded's initializer reads the collector itself
    function ClassInfoCollector(::Val{:_}, translator::KernelNodes)
        local self
        self = new(translator, Late{ClassInfo}("dart2wasm/lib/class_info.dart:348 ClassInfoCollector.topInfo"),
                   Dict{Int,WasmBuilder.IR.StructType}(),
                   Late{Base.IdSet{DataType}}("dart2wasm/lib/class_info.dart:357 ClassInfoCollector.masqueraded", () -> _compute_masquerades(self)),
                   Late{WasmBuilder.IR.FieldType}("dart2wasm/lib/class_info.dart:401 ClassInfoCollector.typeType"))
        return self
    end
end

"""
The closed world's class ids: one depth-first pre-order walk of the class tree from `Any`, each
concrete class the next concrete id from 1 (0 is the artificial top class), each abstract class an
id after the last concrete one, and each class the ranges of the concrete ids under it and under
its implementors (the tree walk's model, dev/formal/ClassIdNumbering.tla). A class is a Julia `DataType`, keyed by identity: Julia calls
`Core.TypeofBottom` and its supertype `Type{Union{}}` equal types, two classes all the same.

The translator is held as `KernelNodes`, the mixin Translator alone applies (src/translator.jl):
precedent(dart: `class Translator with KernelNodes`, the mixin a field may be typed by; rust: a
trait object breaking a cycle of struct types). Julia's differs: two structs cannot name each
other, so the collaborator names the abstract type only Translator subtypes.
"""
@parity "dart2wasm/lib/class_info.dart:780 ClassIdNumbering" struct ClassIdNumbering
    translator::KernelNodes
    _subclasses::IdDict{DataType,Vector{DataType}}
    _implementors::IdDict{DataType,Vector{DataType}}
    _concrete_subclass_id_range::IdDict{DataType,Vector{Range}}
    _masqueraded::Base.IdSet{DataType}
    dfs_order::Vector{DataType}
    class_ids::IdDict{DataType,Int}
    max_concrete_class_id::Int
    max_class_id::Int
    _transitive_implementors::IdDict{DataType,Base.IdSet{DataType}}
    _concrete_class_id_ranges::IdDict{DataType,Vector{Range}}
    first_non_masqueraded_interface_class_cid::Late{Int}
    # dart's constructor `ClassIdNumbering._` with its field initializers, the struct's one
    # constructor tagged by the dart name; the late field's initializer reads the numbering itself
    function ClassIdNumbering(::Val{:_}, translator::KernelNodes, _subclasses::IdDict{DataType,Vector{DataType}},
            _implementors::IdDict{DataType,Vector{DataType}}, _concrete_subclass_id_range::IdDict{DataType,Vector{Range}},
            _masqueraded::Base.IdSet{DataType}, dfs_order::Vector{DataType}, class_ids::IdDict{DataType,Int},
            max_concrete_class_id::Int, max_class_id::Int)
        local self
        local cid = Late{Int}("dart2wasm/lib/class_info.dart:853 ClassIdNumbering.firstNonMasqueradedInterfaceClassCid", function ()
            local last_masqueraded_class_id = 0
            for cls in self._masqueraded
                local ranges = get_concrete_class_id_range(self, cls)
                isempty(ranges) || (last_masqueraded_class_id = max(last_masqueraded_class_id, ranges[end].end_))
            end
            return last_masqueraded_class_id + 1
        end)
        self = new(translator, _subclasses, _implementors, _concrete_subclass_id_range, _masqueraded, dfs_order,
                         class_ids, max_concrete_class_id, max_class_id, IdDict{DataType,Base.IdSet{DataType}}(),
                         IdDict{DataType,Vector{Range}}(), cid)
        return self
    end
end

"""A range of class ids, both ends inclusive."""
@parity "dart2wasm/lib/class_info.dart:1059 Range" struct Range
    start::Int
    end_::Int
    # dart's generative constructors `Range._` and `Range.empty`, the struct's one constructor tagged by
    # the dart name (Julia has no named constructors, and the factory `Range(start, end)` takes the
    # default constructor's signature)
    Range(::Val{:_}, start::Int, end_::Int) = new(start, end_)
end

